package de.taxil150.app;
import android.app.*;import android.content.*;import android.media.*;import android.net.Uri;import java.text.DateFormat;import java.util.Date;
public final class Alerts {
 public static final String CHANNEL="calls_zurna_v2";
 public static void ensure(Context c){NotificationManager nm=c.getSystemService(NotificationManager.class);NotificationChannel channel=new NotificationChannel(CHANNEL,"Taxi-Aufruf · Zurna",NotificationManager.IMPORTANCE_HIGH);channel.setLockscreenVisibility(Notification.VISIBILITY_PUBLIC);channel.enableVibration(true);channel.setVibrationPattern(new long[]{0,400,180,400,180,650});channel.setSound(Uri.parse("android.resource://"+c.getPackageName()+"/"+R.raw.zurna),new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_NOTIFICATION).build());nm.createNotificationChannel(channel);}
 public static String blocked(Context c){ensure(c);NotificationManager nm=c.getSystemService(NotificationManager.class);if(!nm.areNotificationsEnabled())return "Benachrichtigungen für die App sind gesperrt";NotificationChannel ch=nm.getNotificationChannel(CHANNEL);if(ch==null||ch.getImportance()==NotificationManager.IMPORTANCE_NONE)return "Kategorie Taxi-Aufruf ist ausgeschaltet";return "";}
 public static String tone(Context c){ensure(c);Uri uri=c.getSystemService(NotificationManager.class).getNotificationChannel(CHANNEL).getSound();if(uri==null)return "Aus / lautlos";if(uri.toString().startsWith("android.resource://"+c.getPackageName()+"/"))return "Zurna";try{Ringtone r=RingtoneManager.getRingtone(c,uri);return r==null?"Gewählter Systemton":r.getTitle(c);}catch(Exception e){return "Gewählter Systemton (Name nicht verfügbar)";}}
 public static String diagnostics(Context c){String b=blocked(c);if(!b.isEmpty())return b;NotificationChannel ch=c.getSystemService(NotificationManager.class).getNotificationChannel(CHANNEL);AudioManager audio=c.getSystemService(AudioManager.class);String result="Benachrichtigungen erlaubt";if(ch.getImportance()<NotificationManager.IMPORTANCE_DEFAULT)result+=" · Kategorie ist leise";if(audio.getRingerMode()==AudioManager.RINGER_MODE_SILENT)result+=" · Handy ist lautlos";else if(audio.getRingerMode()==AudioManager.RINGER_MODE_VIBRATE)result+=" · Handy ist im Vibrationsmodus";if(audio.getStreamVolume(AudioManager.STREAM_NOTIFICATION)==0)result+=" · Benachrichtigungslautstärke 0";if(c.getSystemService(NotificationManager.class).getCurrentInterruptionFilter()!=NotificationManager.INTERRUPTION_FILTER_ALL)result+=" · Nicht stören ist aktiv";return result;}
 public static Intent settings(Context c){ensure(c);if(!c.getSystemService(NotificationManager.class).areNotificationsEnabled())return new Intent("android.settings.APP_NOTIFICATION_SETTINGS").putExtra("android.provider.extra.APP_PACKAGE",c.getPackageName());return new Intent("android.settings.CHANNEL_NOTIFICATION_SETTINGS").putExtra("android.provider.extra.APP_PACKAGE",c.getPackageName()).putExtra("android.provider.extra.CHANNEL_ID",CHANNEL);}
 // Success means Android accepted notify(); actual sound or display cannot be confirmed here.
 public static boolean post(Context c,String number,String target,boolean test){String blocked=blocked(c);android.content.SharedPreferences p=c.getSharedPreferences("status",0);String key=test?"testAlarm":"lastAlarm";if(!blocked.isEmpty()){p.edit().putString(key,"Blockiert: "+blocked).apply();return false;}String body=test?"Testalarm – kein echter APCOA-Aufruf":"Zielbereich: "+(target.isEmpty()?"nicht angegeben":target);PendingIntent open=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);try{c.getSystemService(NotificationManager.class).notify(test?3:2,new Notification.Builder(c,CHANNEL).setSmallIcon(android.R.drawable.ic_dialog_alert).setContentTitle(test?"TAXI "+number+" – TESTALARM":"TAXI "+number+" – AUFGERUFEN!").setContentText(body).setStyle(new Notification.BigTextStyle().bigText(body)).setVisibility(Notification.VISIBILITY_PUBLIC).setContentIntent(open).setAutoCancel(true).setOnlyAlertOnce(false).build());p.edit().putString(key,"An Android übergeben: "+DateFormat.getDateTimeInstance().format(new Date())).apply();return true;}catch(Exception e){p.edit().putString(key,"Fehler: "+e.getMessage()).apply();return false;}}
}
